const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.4 1.4m11.2 11.2L19 19M5 19l1.4-1.4M17.6 6.4 19 5"/>','check-circle':'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',sparkles:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/><path d="M20 2v4m-2-2h4"/>',chevrons:'<path d="m8 9 4-4 4 4m-8 6 4 4 4-4"/>',more:'<circle cx="5" cy="12" r=".7"/><circle cx="12" cy="12" r=".7"/><circle cx="19" cy="12" r=".7"/>',layout:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M9 4v16"/>',plus:'<path d="M12 5v14M5 12h14"/>',layers:'<path d="m12 3 10 5-10 5L2 8l10-5Zm-9 9 9 5 9-5M3 16l9 5 9-5"/>',flame:'<path d="M12 3s2 5-2 8c-2-3-3-3-3-3s-3 4-3 7a8 8 0 0 0 16 0c0-6-8-12-8-12Z"/><path d="M12 13s-3 3-3 5a3 3 0 0 0 6 0c0-2-3-5-3-5Z"/>',list:'<path d="M9 6h12M9 12h12M9 18h12M3 6h1M3 12h1M3 18h1"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v4h16v-4"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 0 1 5 .5c0 1.5-2.5 1.5-2.5 4M12 17h.01"/>',move:'<path d="M12 3v18M3 12h18M9 6l3-3 3 3M9 18l3 3 3-3M6 9l-3 3 3 3m12-6 3 3-3 3"/>',panel:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M15 4v16m-5-12 3 4-3 4"/>','arrow-up-right':'<path d="M6 18 18 6M6 6h12v12"/>','arrow-up':'<path d="M12 19V5m-6 6 6-6 6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',x:'<path d="m6 6 12 12M6 18 18 6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>'};
const svg=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.grid}</svg>`;
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=svg(el.dataset.icon));
const $=id=>document.getElementById(id);
const escapeHtml=text=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const quadrants=[{id:1,title:'Сделать',subtitle:'Срочно и важно',hint:'Первым делом — то, что требует твоего внимания сейчас.'},{id:2,title:'Запланировать',subtitle:'Важно, но не срочно',hint:'Инвестируй время в то, что приближает к большим целям.'},{id:3,title:'Делегировать',subtitle:'Срочно, но не важно',hint:'Подумай, что можно передать другому или упростить.'},{id:4,title:'Отпустить',subtitle:'Не срочно и не важно',hint:'Убери лишнее. А для отдыха оставь осознанное время.'}];
const seed=[{id:1,title:'Подготовить презентацию проекта',q:1,tag:'Работа',date:'Сегодня',note:'Собрать главные результаты и подготовить 5 слайдов.',done:false},{id:2,title:'Оплатить счёт за интернет',q:1,tag:'Личное',date:'Сегодня',note:'Срок оплаты подходит к концу.',done:false},{id:3,title:'Продумать цели на ноябрь',q:2,tag:'Развитие',date:'На неделе',note:'Выделить три главных направления.',done:false},{id:4,title:'Позаниматься английским',q:2,tag:'Обучение',date:'Без спешки',note:'20 минут практики каждый день.',done:false},{id:5,title:'Записаться на чекап',q:2,tag:'Здоровье',date:'На неделе',note:'Позаботиться о себе заранее.',done:false},{id:6,title:'Заказать продукты домой',q:3,tag:'Быт',date:'Завтра',note:'Можно заказать доставку.',done:false},{id:7,title:'Ответить в рабочем чате',q:3,tag:'Работа',date:'Сегодня',note:'Уточнить, какие вопросы требуют ответа.',done:false},{id:8,title:'Посмотреть новый сериал',q:4,tag:'Отдых',date:'Когда захочется',note:'Оставить на свободный вечер.',done:false}];
let tasks;try{const saved=JSON.parse(localStorage.getItem('taskmaster.design.v1'));tasks=Array.isArray(saved)&&saved.every(t=>Number.isInteger(t.id)&&typeof t.title==='string'&&[1,2,3,4].includes(t.q))?saved:structuredClone(seed);}catch{tasks=structuredClone(seed)}
let nav='matrix',view='matrix',editingId=null,dragId=null,toastTimer;
const notify=message=>{$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3200)};
function save(){try{localStorage.setItem('taskmaster.design.v1',JSON.stringify(tasks))}catch{notify('Хранилище браузера недоступно. Изменения сохранены на время сеанса.')}render()}
function visibleTasks(){const term=$('search').value.trim().toLowerCase();return tasks.filter(t=>(nav==='completed'?t.done:!t.done)&&(nav!=='focus'||t.q===1)&&(!term||`${t.title} ${t.note||''} ${t.tag||''}`.toLowerCase().includes(term)))}
function taskCard(t){return `<article class="task ${t.done?'completed':''}" draggable="true" data-id="${t.id}"><div class="task-top"><button class="task-check" data-complete="${t.id}" aria-label="${t.done?'Вернуть задачу':'Завершить задачу'}: ${escapeHtml(t.title)}">${t.done?svg('check'):''}</button><button class="task-title" data-edit="${t.id}">${escapeHtml(t.title)}</button><button class="task-more" data-edit="${t.id}" aria-label="Редактировать: ${escapeHtml(t.title)}">${svg('more')}</button></div><div class="task-meta"><span class="task-tag">${escapeHtml(t.tag||'Личное')}</span><span class="task-date ${t.date==='Сегодня'?'today':''}">${svg('calendar')}${escapeHtml(t.date||'Без срока')}</span></div></article>`}
function render(){const visible=visibleTasks();$('board').classList.toggle('list-mode',view==='list');$('board').innerHTML=quadrants.filter(q=>nav!=='focus'||q.id===1).map(q=>{const items=visible.filter(t=>t.q===q.id);return `<section class="quadrant" data-q="${q.id}" aria-label="${q.title}: ${q.subtitle}"><div class="quadrant-header"><span class="quadrant-number">0${q.id}</span><div><h2>${q.title}</h2><p>${q.subtitle}</p></div><span class="quadrant-count">${items.length}</span></div><div class="tasks">${items.length?items.map(taskCard).join(''):`<div class="empty-state">${$('search').value?'Ничего не найдено':nav==='completed'?'Здесь появятся завершённые задачи':'Пока свободно.<br>Оставь место для важного.'}</div>`}</div>${nav!=='completed'?`<button class="quadrant-add" data-add="${q.id}">${svg('plus')}Добавить задачу</button>`:''}</section>`}).join('');
 const active=tasks.filter(t=>!t.done).length,done=tasks.filter(t=>t.done).length;$('total-count').textContent=active;$('urgent-count').textContent=tasks.filter(t=>!t.done&&t.q===1).length;$('nav-count').textContent=active;$('progress-count').textContent=`${done}/${tasks.length}`;$('progress-fill').style.width=`${tasks.length?done/tasks.length*100:0}%`;$('progress-label').textContent=done?'Каждый шаг имеет значение':'Начнём с одного маленького шага';document.querySelector('.matrix-axis').hidden=view==='list'||nav==='focus';
 $('board').querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>openTask(Number(b.dataset.add)));$('board').querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openTask(null,Number(b.dataset.edit)));$('board').querySelectorAll('[data-complete]').forEach(b=>b.onclick=()=>{const t=tasks.find(t=>t.id===Number(b.dataset.complete));t.done=!t.done;save();notify(t.done?'Готово! На одну заботу меньше.':'Задача возвращена в матрицу')});
 document.querySelectorAll('.task').forEach(el=>{el.addEventListener('dragstart',e=>{dragId=Number(el.dataset.id);e.dataTransfer.setData('text/plain',String(dragId));e.dataTransfer.effectAllowed='move';el.classList.add('dragging')});el.addEventListener('dragend',()=>{dragId=null;el.classList.remove('dragging');document.querySelectorAll('.drag-over').forEach(e=>e.classList.remove('drag-over'))})});document.querySelectorAll('.quadrant').forEach(el=>{el.addEventListener('dragover',e=>{if(dragId!==null){e.preventDefault();e.dataTransfer.dropEffect='move';el.classList.add('drag-over')}});el.addEventListener('dragleave',e=>{if(!el.contains(e.relatedTarget))el.classList.remove('drag-over')});el.addEventListener('drop',e=>{e.preventDefault();const task=tasks.find(t=>t.id===dragId);if(task){task.q=Number(el.dataset.q);save();notify('Задача на новом месте')}})})}
function openTask(q=1,id=null){editingId=id;const t=tasks.find(t=>t.id===id);$('dialog-title').textContent=t?'Детали задачи':'Новая задача';$('task-title').value=t?.title||'';$('task-quadrant').value=t?.q||q||1;$('task-note').value=t?.note||'';$('delete-task').hidden=!t;$('task-dialog').showModal();$('task-title').focus()}
function nextId(){return Math.max(0,...tasks.map(t=>t.id))+1}
$('task-form').onsubmit=e=>{e.preventDefault();const title=$('task-title').value.trim();if(!title){$('task-title').setCustomValidity('Введи название задачи');$('task-title').reportValidity();return}const values={title,q:Number($('task-quadrant').value),note:$('task-note').value.trim()};const task=tasks.find(t=>t.id===editingId);if(task)Object.assign(task,values);else tasks.push({id:nextId(),...values,tag:'Личное',date:'Без срока',done:false});save();$('task-dialog').close();notify(task?'Изменения сохранены':'У новой задачи появилось своё место')};$('task-title').oninput=()=>$('task-title').setCustomValidity('');
$('add-task').onclick=()=>openTask();$('close-dialog').onclick=()=>$('task-dialog').close();$('delete-task').onclick=()=>{tasks=tasks.filter(t=>t.id!==editingId);save();$('task-dialog').close();notify('Задача удалена')};$('search').oninput=render;
document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{nav=b.dataset.nav;document.querySelectorAll('[data-nav]').forEach(n=>n.classList.toggle('active',n===b));$('breadcrumb-title').textContent={matrix:'Моя матрица',focus:'В фокусе',completed:'Завершённые'}[nav];$('page-title').innerHTML={matrix:'Освободи голову.<br><span>Найди свой фокус.</span>',focus:'Одно за другим.<br><span>Начни с главного.</span>',completed:'Маленькие победы.<br><span>Большое движение.</span>'}[nav];$('page-description').textContent={matrix:'Собери мысли в задачи, а задачи — в понятный план.',focus:'Срочные и важные дела, которым нужно твоё внимание.',completed:'Посмотри, сколько всего уже осталось позади.'}[nav];render()});
function setView(next){view=next;$('matrix-view').classList.toggle('selected',view==='matrix');$('list-view').classList.toggle('selected',view==='list');render()}$('matrix-view').onclick=()=>setView('matrix');$('list-view').onclick=()=>setView('list');
$('today').textContent=new Intl.DateTimeFormat('ru-RU',{weekday:'short',day:'numeric',month:'long',timeZone:'Europe/Istanbul'}).format(new Date());
$('guide-content').innerHTML=quadrants.map(q=>`<div class="guide-row"><strong>0${q.id} · ${q.title}</strong><p>${q.subtitle}. ${q.hint}</p></div>`).join('');$('guide').onclick=()=>$('info-dialog').showModal();$('close-info').onclick=$('got-it').onclick=()=>$('info-dialog').close();$('profile').onclick=$('workspace').onclick=()=>$('info-dialog').showModal();
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
$('open-assistant').onclick=()=>$('assistant').classList.add('open');$('close-assistant').onclick=()=>{if(matchMedia('(max-width:1050px)').matches){$('assistant').classList.remove('open');$('open-assistant').focus()}else{notify('Напиши о планах — начнём с одной задачи.');$('chat-input').focus()}};document.addEventListener('keydown',e=>{if(e.key==='Escape')$('assistant').classList.remove('open')});
$('export').onclick=()=>{const fields=['ID','Задача','Квадрант','Обоснование','Завершена'];const safeCell=v=>'"'+String(v).replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"';const rows=[fields,...tasks.map(t=>[t.id,t.title,t.q,t.note||'',t.done?'Да':'Нет'])];const blob=new Blob(['\uFEFF'+rows.map(row=>row.map(safeCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='taskmaster-matrix.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Матрица экспортирована в CSV')};
function sendMessage(){const text=$('chat-input').value.trim();if(!text)return;if(text.length>500){notify('Для демо напиши одну задачу до 500 символов');return}$('chat-input').value='';document.querySelector('.prompt-list').hidden=true;const user=document.createElement('div');user.className='chat-user';user.textContent=text;$('messages').append(user);const reply=document.createElement('div');reply.className='chat-reply';reply.textContent='В демо ты выбираешь приоритет сам. После подключения AI здесь появятся предложенный квадрант и объяснение.';$('messages').append(reply);const draft=document.createElement('div');draft.className='suggestion';draft.innerHTML=`<strong>${escapeHtml(text)}</strong><select aria-label="Квадрант для новой задачи">${quadrants.map(q=>`<option value="${q.id}" ${q.id===2?'selected':''}>0${q.id} · ${q.title}</option>`).join('')}</select><button>Добавить в матрицу ${svg('plus')}</button>`;draft.querySelector('button').onclick=()=>{tasks.push({id:nextId(),title:text,q:Number(draft.querySelector('select').value),note:'Добавлено из демо-диалога',tag:'Личное',date:'Без срока',done:false});save();draft.querySelector('button').textContent='Добавлено ✓';draft.querySelector('button').disabled=true;draft.querySelector('select').disabled=true;notify('Задача добавлена в матрицу')};$('messages').append(draft);$('chat-scroll').scrollTop=$('chat-scroll').scrollHeight}
$('send').onclick=sendMessage;$('chat-input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();sendMessage()}};document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>{$('chat-input').value=b.dataset.prompt;$('chat-input').focus()});render();
